$ErrorActionPreference='Stop'
$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'))
$zip=Get-ChildItem -LiteralPath (Join-Path $root 'outputs') -Filter 'ACTUALIZACION_V477_COMPLETA_PRIVADA_MONSTERASP_*.zip'|Sort-Object LastWriteTime -Descending|Select-Object -First 1
if(!$zip){throw 'No se encontró el paquete V477'}
Add-Type -AssemblyName System.IO.Compression.FileSystem
$archive=[IO.Compression.ZipFile]::OpenRead($zip.FullName)
function Read-Entry([string]$name){$entry=$archive.GetEntry($name);if(!$entry){throw "Falta $name"};$reader=[IO.StreamReader]::new($entry.Open());try{$reader.ReadToEnd()}finally{$reader.Dispose()}}
try{foreach($prefix in @('','wwwroot/')){$version=(Read-Entry ($prefix+'wwwroot/version-web.json'))|ConvertFrom-Json;if($version.release-ne'V477'-or$version.voiceOperations-ne'verified-complete-active-agency-catalog-search-v477'){throw 'Marcadores V477 incorrectos'};$config=Read-Entry ($prefix+'web.config');if($config-notmatch'RegistroAgencias.SqlServer.V477.exe'){throw 'Ejecutable incorrecto'};$xml=[xml]$config;$credential=$xml.SelectSingleNode("//environmentVariable[@name='STORAGE_KEY']");if(!$credential-or[string]::IsNullOrWhiteSpace($credential.GetAttribute('value'))){throw 'Falta almacenamiento privado'};$scripts=($archive.Entries|Where-Object {$_.FullName-like($prefix+'wwwroot/assets/*.js')}|ForEach-Object {Read-Entry $_.FullName})-join"`n";$styles=($archive.Entries|Where-Object {$_.FullName-like($prefix+'wwwroot/assets/*.css')}|ForEach-Object {Read-Entry $_.FullName})-join"`n";foreach($marker in @('Catálogos verificados','El catálogo de agencias está incompleto','Catálogo de agencias activas','Buscar agencia','No hay agencias con ese texto')){if(!$scripts.Contains($marker)){throw "Falta verificación de agencias: $marker"}};foreach($marker in @('.admin-voice-agency-picker','.admin-voice-agency-results')){if(!$styles.Contains($marker)){throw "Falta estilo del catálogo: $marker"}};if(!$archive.GetEntry($prefix+'RegistroAgencias.SqlServer.V477.dll')-or!$archive.GetEntry($prefix+'RegistroAgencias.SqlServer.V477.exe')){throw 'Falta API V477'}};if($archive.Entries.FullName|Where-Object {$_-match'(^|/)(\.env[^/]*|appsettings[^/]*|app_offline\.htm)$|(^|/)(App_Data|uploads|logs|node_modules)/'}){throw 'Contenido no permitido'}}finally{$archive.Dispose()}
$hash=(Get-FileHash -LiteralPath $zip.FullName -Algorithm SHA256).Hash
Set-Content -LiteralPath ($zip.FullName+'.sha256.txt') -Value "$hash  $($zip.Name)" -Encoding ascii
[pscustomobject]@{Zip=$zip.FullName;MB=[Math]::Round($zip.Length/1MB,2);SHA256=$hash;AllActiveAgencies='verified';DatabaseTotalCheck='verified';AgencySearch='verified';NoEightItemLimit='verified';Release='V477'}|ConvertTo-Json
